// admin/website — GridCommerce's public website (gridcommerce.net) as the super admin manages it: Website › Pages,
// Content, Blog and SEO. Front end only: createStore key `website` (localStorage gc.admin.website). Nothing here
// changes the live site; publishing only moves the demo record (the pages say so with a toast).
//
// Where the data comes from: SNAP (below, generated once from the website repo ~/Documents/gricommercev1 at commit
// 223367b, 8 Oct 2026, by a script that read its typed data files; never hand-edit the long line):
//   SNAP.pages     every route in its src/app (+ the help categories and blog posts it prerenders), with the title and
//                  description each page.tsx passes to buildMetadata({ title, description, path }) in src/lib/seo.tsx,
//                  its type (Home / Feature / Solution / Pricing / Legal / Help / Blog / Utility) and `sections` (block ids).
//   SNAP.fields    [key, English, Bangla | null] — every text the blocks show; Bangla null = one value in both languages
//                  (names, links, prices). '__PENDING__' = site.ts' PENDING (shown as "to be confirmed" on the site).
//   SNAP.blocks    { id: { label, source ('src/data/... › EXPORT'), keys: [field index] } }
//   SNAP.groups    the Content page's editors (Homepage, Product & features, Pricing, FAQs, Testimonials, Company
//                  information, Navigation menu, Footer, Other pages) as lists of block ids.
//   SNAP.articles  src/data/sample/articles.ts › ARTICLES; SNAP.cats › BLOG_CATEGORIES; SNAP.sitemap what sitemap.ts
//                  lists ('!' = a folder with no page.tsx); SNAP.robots robots.ts; SNAP.site site.ts › SITE.
//
// Store (seeded around `now`):
//   pages: { [path]: { status, updatedAt, editor, submittedBy, approvedBy, pub: { title, description } | null,
//            draft: { title, description } | null, note, versions: [{ id, at, by, kind, title, description }] } }
//   edits: { [fieldKey]: { en, bn, by, at } }  content waiting to publish · live: { [fieldKey]: { en, bn } } published edits
//   groups: { [groupId]: { status, by, at, submittedBy, approvedBy, note, history: [{ at, by, text }] } }
//   seo: { [path]: { seoTitle, metaDesc, slug, index, ogTitle, ogDesc, ogImage, at, by } }   (overrides only)
//   posts: [{ slug, title: {en,bn}, excerpt: {en,bn}, body: {en,bn}, author, cat, cover, seoTitle, metaDesc, status,
//             publishAt, updatedAt, editor, submittedBy, approvedBy, read, versions: [{ id, at, by, kind, title }] }]
//   cats: [{ slug, en, bn }] · authors: [{ id, name, role, bio }] · log: [{ at, by, text, path }]
// Workflow everywhere: Draft → In review → Approved → Published (posts: Scheduled when the publish date is ahead).
// The person who submitted cannot approve. Change functions commit and return { ok, error? }.

import { createStore } from './store';
import { DAY, MIN, rng } from '@/lib/platform/util';

// prettier-ignore
